NativeSignal configure_sprite_mode(
    VM& vm, Thread& thread, uint32_t mode,
    std::size_t operand_count) {
    std::vector<uint32_t> operands(operand_count);
    for (std::size_t index = operand_count; index != 0; --index) {
        operands[index - 1] = thread.stack.pop();
    }
    if (mode == 0U && debug_trace(DebugTrace::Control)) {
        std::cerr << "SPRITE_MODE_ZERO operands=";
        for (const auto value : operands) std::cerr << value << ',';
        std::cerr << '\n';
    }
    const uint32_t status = vm.set_sprite_mode_configuration(
        operands.front(), mode, operands);
    if (status != 0) {
        std::ostringstream message;
        message << "Grp0 sprite mode " << mode
                << " configuration failed with status 0x"
                << std::hex << std::uppercase << status;
        throw std::runtime_error(message.str());
    }
    return NativeSignal::Continue;
}
